// pluck_hmm.dice, translated by tddlog's scripts/dice2psi.py, component 0.
def f_step(v1_s: 𝔹 × 𝔹) {
  v2_z := v1_s[0];
  v3_seen := v1_s[1];
  v6_next := false;
  if v2_z { v4_next := flip(0.7); v6_next = v4_next; } else { v5_next := flip(0.1); v6_next = v5_next; }
  v9_shown := false;
  if v6_next { v7_shown := flip(0.3); v9_shown = v7_shown; } else { v8_shown := flip(0.6); v9_shown = v8_shown; }
  v10_step := (v3_seen && v9_shown);
  v11_step := (v6_next, v10_step);
  return v11_step;
}

def main() {
  v12_result := (false, true);
  v13_state := v12_result;
  for _ in [0..50) { v13_state = f_step(v13_state); }
  v14_result := v13_state[1];
  return v14_result;
}

