// pluck_hmm.dice, translated by tddlog's scripts/dice2webppl.py.
// component 0 bool

var iterate = function(f, x, k) {
  return k == 0 ? x : iterate(f, f(x), k - 1);
};

var step = function(s) {
  var z = s[0];
  var seen = s[1];
  var next = z ? flip(0.7) : flip(0.1);
  var shown = next ? flip(0.3) : flip(0.6);
  return [next, seen && shown];
};

var model = function() {
  return iterate(step, [false, true], 50)[1];
};

Infer({method: 'enumerate'}, model);

