x1 := 1;
loop 50 {
    if x0 = 1 {
        x2 ~ Bernoulli(0.7);
        x3 := x2;
        x2 := 0;
    } else {
        x2 ~ Bernoulli(0.1);
        x3 := x2;
        x2 := 0;
    }
    if x3 = 1 {
        x2 ~ Bernoulli(0.3);
        x4 := x2;
        x2 := 0;
    } else {
        x2 ~ Bernoulli(0.6);
        x4 := x2;
        x2 := 0;
    }
    if (x1 = 1) && (x4 = 1) { x2 := 1; } else { x2 := 0; }
    x4 := 0;
    x0 := x3;
    x1 := x2;
}
